import json
import re
from typing import Callable, Dict, Iterable, List, Optional, Sequence, Tuple, Union


class CORSConfig:
    """Configuration container for CORS policy rules."""

    def __init__(
        self,
        allow_origins: Sequence[str] = ("*",),
        allow_methods: Sequence[str] = ("GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS"),
        allow_headers: Sequence[str] = ("Content-Type", "Authorization", "X-Requested-With"),
        expose_headers: Sequence[str] = (),
        allow_credentials: bool = False,
        max_age: int = 86400,
    ) -> None:
        self.allow_origins = list(allow_origins)
        self.allow_methods = [m.upper() for m in allow_methods]
        self.allow_headers = [h.lower() for h in allow_headers]
        self.expose_headers = list(expose_headers)
        self.allow_credentials = allow_credentials
        self.max_age = max_age
        self._compiled_regexes = [
            re.compile(f"^{re.escape(origin).replace(r'\*', '.*')}$")
            for origin in self.allow_origins
            if "*" in origin and origin != "*"
        ]

    def is_origin_allowed(self, origin: str) -> bool:
        if "*" in self.allow_origins:
            return True
        if origin in self.allow_origins:
            return True
        return any(regex.match(origin) is not None for regex in self._compiled_regexes)

    def are_headers_allowed(self, request_headers: Sequence[str]) -> bool:
        if "*" in self.allow_headers:
            return True
        return all(h.strip().lower() in self.allow_headers for h in request_headers if h.strip())

    def is_method_allowed(self, method: str) -> bool:
        return method.upper() in self.allow_methods


class CORSMiddleware:
    """
    WSGI Middleware implementing Cross-Origin Resource Sharing (CORS) specification.
    Handles both preflight (OPTIONS) requests and actual API requests.
    """

    def __init__(self, app: Callable, config: Optional[CORSConfig] = None) -> None:
        self.app = app
        self.config = config or CORSConfig()

    def __call__(self, environ: Dict, start_response: Callable) -> Iterable[bytes]:
        method = environ.get("REQUEST_METHOD", "GET").upper()
        origin = environ.get("HTTP_ORIGIN")

        if not origin:
            return self.app(environ, start_response)

        if method == "OPTIONS" and "HTTP_ACCESS_CONTROL_REQUEST_METHOD" in environ:
            return self._handle_preflight(environ, start_response, origin)

        return self._handle_actual_request(environ, start_response, origin)

    def _handle_preflight(self, environ: Dict, start_response: Callable, origin: str) -> Iterable[bytes]:
        req_method = environ.get("HTTP_ACCESS_CONTROL_REQUEST_METHOD", "")
        req_headers_raw = environ.get("HTTP_ACCESS_CONTROL_REQUEST_HEADERS", "")
        req_headers = [h.strip() for h in req_headers_raw.split(",") if h.strip()]

        headers: List[Tuple[str, str]] = [("Content-Length", "0")]

        if not self.config.is_origin_allowed(origin):
            start_response("403 Forbidden", [("Content-Length", "0")])
            return [b""]

        if not self.config.is_method_allowed(req_method):
            start_response("405 Method Not Allowed", [("Content-Length", "0")])
            return [b""]

        if not self.config.are_headers_allowed(req_headers):
            start_response("403 Forbidden", [("Content-Length", "0")])
            return [b""]

        self._apply_cors_headers(headers, origin)
        headers.append(("Access-Control-Allow-Methods", ", ".join(self.config.allow_methods)))

        if req_headers_raw:
            headers.append(("Access-Control-Allow-Headers", req_headers_raw))
        else:
            headers.append(("Access-Control-Allow-Headers", ", ".join(self.config.allow_headers)))

        if self.config.max_age > 0:
            headers.append(("Access-Control-Max-Age", str(self.config.max_age)))

        start_response("204 No Content", headers)
        return [b""]

    def _handle_actual_request(self, environ: Dict, start_response: Callable, origin: str) -> Iterable[bytes]:
        cors_headers: List[Tuple[str, str]] = []

        if self.config.is_origin_allowed(origin):
            self._apply_cors_headers(cors_headers, origin)
            if self.config.expose_headers:
                cors_headers.append(
                    ("Access-Control-Expose-Headers", ", ".join(self.config.expose_headers))
                )

        def custom_start_response(status: str, response_headers: List[Tuple[str, str]], exc_info=None):
            merged_headers = list(response_headers) + cors_headers
            return start_response(status, merged_headers, exc_info)

        return self.app(environ, custom_start_response)

    def _apply_cors_headers(self, headers: List[Tuple[str, str]], origin: str) -> None:
        if self.config.allow_credentials:
            headers.append(("Access-Control-Allow-Origin", origin))
            headers.append(("Access-Control-Allow-Credentials", "true"))
            headers.append(("Vary", "Origin"))
        else:
            if "*" in self.config.allow_origins:
                headers.append(("Access-Control-Allow-Origin", "*"))
            else:
                headers.append(("Access-Control-Allow-Origin", origin))
                headers.append(("Vary", "Origin"))


class SimpleAPI:
    """Minimal WSGI JSON API implementation."""

    def __init__(self) -> None:
        self.routes: Dict[Tuple[str, str], Callable] = {}
        self._register_routes()

    def _register_routes(self) -> None:
        self.routes[("GET", "/api/items")] = self.get_items
        self.routes[("POST", "/api/items")] = self.create_item

    def get_items(self, environ: Dict) -> Tuple[str, List[Tuple[str, str]], bytes]:
        data = {"items": ["item1", "item2", "item3"], "status": "success"}
        body = json.dumps(data).encode("utf-8")
        headers = [
            ("Content-Type", "application/json"),
            ("Content-Length", str(len(body))),
            ("X-Custom-Server-Meta", "ItemStore-v1"),
        ]
        return "200 OK", headers, body

    def create_item(self, environ: Dict) -> Tuple[str, List[Tuple[str, str]], bytes]:
        try:
            content_length = int(environ.get("CONTENT_LENGTH", 0))
            payload = environ["wsgi.input"].read(content_length)
            item_data = json.loads(payload.decode("utf-8"))
        except (ValueError, KeyError):
            body = json.dumps({"error": "Invalid JSON"}).encode("utf-8")
            return "400 Bad Request", [("Content-Type", "application/json"), ("Content-Length", str(len(body)))], body

        response_data = {"status": "created", "received": item_data}
        body = json.dumps(response_data).encode("utf-8")
        headers = [
            ("Content-Type", "application/json"),
            ("Content-Length", str(len(body))),
        ]
        return "201 Created", headers, body

    def __call__(self, environ: Dict, start_response: Callable) -> Iterable[bytes]:
        method = environ.get("REQUEST_METHOD", "").upper()
        path = environ.get("PATH_INFO", "")
        handler = self.routes.get((method, path))

        if handler:
            status, headers, body = handler(environ)
            start_response(status, headers)
            return [body]

        body = json.dumps({"error": "Not Found"}).encode("utf-8")
        start_response("404 Not Found", [("Content-Type", "application/json"), ("Content-Length", str(len(body)))])
        return [body]


def build_app(config: Optional[CORSConfig] = None) -> Callable:
    """Builds and returns the WSGI application with CORS middleware attached."""
    api = SimpleAPI()
    return CORSMiddleware(api, config)


def simulate_wsgi_request(
    app: Callable,
    method: str,
    path: str,
    headers: Optional[Dict[str, str]] = None,
    body: bytes = b"",
) -> Tuple[str, Dict[str, str], bytes]:
    """Helper function to execute simulated WSGI requests and capture responses."""
    import io

    headers = headers or {}
    environ = {
        "REQUEST_METHOD": method.upper(),
        "PATH_INFO": path,
        "SERVER_NAME": "localhost",
        "SERVER_PORT": "8080",
        "wsgi.version": (1, 0),
        "wsgi.url_scheme": "http",
        "wsgi.input": io.BytesIO(body),
        "wsgi.errors": io.StringIO(),
        "wsgi.multithread": False,
        "wsgi.multiprocess": False,
        "wsgi.run_once": False,
        "CONTENT_LENGTH": str(len(body)),
    }

    for key, val in headers.items():
        formatted_key = key.upper().replace("-", "_")
        if formatted_key in ("CONTENT_TYPE", "CONTENT_LENGTH"):
            environ[formatted_key] = val
        else:
            environ[f"HTTP_{formatted_key}"] = val

    captured_status = []
    captured_headers = []

    def start_response(status, resp_headers, exc_info=None):
        captured_status.append(status)
        captured_headers.extend(resp_headers)

    response_chunks = app(environ, start_response)
    response_body = b"".join(response_chunks)
    response_headers = {k: v for k, v in captured_headers}

    return captured_status[0], response_headers, response_body


if __name__ == "__main__":
    cors_policy = CORSConfig(
        allow_origins=["https://trusted-client.com", "https://*.partner.org"],
        allow_methods=["GET", "POST", "OPTIONS"],
        allow_headers=["Content-Type", "Authorization", "X-Custom-Client-Token"],
        expose_headers=["X-Custom-Server-Meta"],
        allow_credentials=True,
        max_age=3600,
    )

    app = build_app(cors_policy)

    # 1. Successful Preflight Request
    preflight_headers = {
        "Origin": "https://trusted-client.com",
        "Access-Control-Request-Method": "POST",
        "Access-Control-Request-Headers": "Content-Type, Authorization",
    }
    status, headers, _ = simulate_wsgi_request(app, "OPTIONS", "/api/items", preflight_headers)
    print("Preflight Check [Allowed]:")
    print(f"  Status: {status}")
    print(f"  Allow-Origin: {headers.get('Access-Control-Allow-Origin')}")
    print(f"  Allow-Methods: {headers.get('Access-Control-Allow-Methods')}")
    print(f"  Allow-Credentials: {headers.get('Access-Control-Allow-Credentials')}")
    print(f"  Max-Age: {headers.get('Access-Control-Max-Age')}\n")

    # 2. Unauthorized Preflight Origin
    disallowed_preflight = {
        "Origin": "https://unauthorized-domain.com",
        "Access-Control-Request-Method": "POST",
    }
    status
